import{z as l,x as B,o as E,c as d,q as r,j as n,D as e,d as t,s as o,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"swap","description":"","frontmatter":{"title":"swap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swap-device.md","filePath":"cs/swap-device.md","lastUpdated":1791413859000}'),A={name:"cs/swap-device.md"};function m(c,a,h,T,w,D){const p=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="swap" tabindex="-1">swap <a class="header-anchor" href="#swap" aria-label="Permalink to &quot;swap&quot;">​</a></h1><div class="epigraph"><p>swap 是一块专用于匿名页的后备空间：按页槽编址，不经文件名，也不保存用户可见的目录树。</p><footer>—— 据 Tanenbaum and Bos, MOS；Bovet and Cesati 对 Linux 交换的整理</footer></div><p><a href="/cs/anon-vs-file-page">上一课</a>规定脏匿名页必须写出。<a href="/cs/disk-sched">磁盘调度</a>尚未到，但块设备已经能接受读写。缺口是<strong>槽位</strong>：交换区是页的数组，内核把「进程 + 虚页」映射到槽，换入时按槽读回帧，再恢复 PTE。不是再做一个用户文件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把每个匿名页写成临时文件，目录与 inode 操作太重，抖动时更糟。经典做法：整块分区或定长 swap 文件，内部只有槽位位图与少量头。缺口：分配槽、写页、在 PTE 或换出表里记下槽号、换入、释放槽。多块 swap 可以有优先级。加密与压缩是实现，不改「页 ↔ 槽」模型。</p><p><span class="marginnote">直觉类比：swap 是给内存配的「溢出书架」。书桌（物理内存）放不下的书按页搬到书架槽位，PTE 上贴一个槽号当索书条；要读时凭号取回——全程不经过图书馆目录（文件系统），这正是它比临时文件轻的原因。</span></p><p>本课不把 hibernation 镜像格式写完。</p><p><span class="marginnote">swap 文件仍占用文件系统空间，但内核用 bmap 记住槽对应哪些块，热路径不再查目录。优先级让快设备先吃换出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>swapon</code> 登记设备。换出：位图取空槽，DMA 写一页，PTE 无效并编码槽（或指向 swap cache 项）。换入：缺页见槽号，读块，填帧，释放槽或留下缓存以免马上再换出。与<a href="/cs/demand-paging">按需调页</a>同一条重试指令路径。槽耗尽则分配失败，下一课 OOM。</p><p><span class="marginnote">数字实例：4 KiB 一页的 8 GB swap 区共有 \\(8\\,\\mathrm{GB}/4\\,\\mathrm{KiB}=2^{21}\\approx 200\\) 万个槽，21 位槽号足够编码——正好塞进 64 位 PTE 换出后空出来的位段里，不用另建表。</span></p>',11)),(E(),n(i,null,{default:e(()=>[o(p,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANON%5B%22%E8%84%8F%E5%8C%BF%E5%90%8D%E9%A1%B5%22%5D%20--%3E%20SLOT%5B%22%E5%88%86%E9%85%8D%20swap%20%E6%A7%BD%22%5D%0A%20%20SLOT%20--%3E%20OUT%5B%22%E5%86%99%E5%87%BA%22%5D%0A%20%20OUT%20--%3E%20IN%5B%22%E7%BC%BA%E9%A1%B5%E8%AF%BB%E5%9B%9E%22%5D%0A%20%20IN%20--%3E%20FREE%5B%22%E9%87%8A%E6%94%BE%E6%A7%BD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"交换设备把 RAM 的下一层从「文件」换成「匿名专用介质」，让堆、栈在物理压力下仍可前进。它放大抖动：每个 major 缺页都是一次块 I/O。工作集控制若失败，swap 吞吐会顶满，CPU 在等盘。不要把关系库的表空间当成 swap；那是数据库栏。",-1)),a[5]||(a[5]=s("p",null,"把一次换入缺页按步骤展开，能看清它贵在哪。",-1)),(E(),n(i,null,{default:e(()=>[o(p,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E7%BC%BA%E9%A1%B5%EF%BC%9APTE%20%E6%97%A0%E6%95%88%E4%B8%94%E8%97%8F%E7%9D%80%E6%A7%BD%E5%8F%B7%22%5D%20--%3E%20QC%7B%22swap%20cache%20%E9%87%8C%E5%B7%B2%E6%9C%89%E8%BF%99%E9%A1%B5%EF%BC%9F%22%7D%0A%20%20QC%20--%20%22%E6%98%AF%22%20--%3E%20HIT%5B%22%E7%9B%B4%E6%8E%A5%E9%87%8D%E5%A1%AB%20PTE%EF%BC%8C%E5%85%8D%20I%2FO%22%5D%0A%20%20QC%20--%20%22%E5%90%A6%22%20--%3E%20IO%5B%22%E6%8C%89%E6%A7%BD%E5%8F%B7%E5%90%91%E5%9D%97%E8%AE%BE%E5%A4%87%E5%8F%91%E8%AF%BB%22%5D%0A%20%20IO%20--%3E%20FILL%5B%22%E8%AF%BB%E5%85%A5%E7%89%A9%E7%90%86%E5%B8%A7%22%5D%0A%20%20FILL%20--%3E%20PTE%5B%22PTE%20%E7%BD%AE%E6%9C%89%E6%95%88%E3%80%81%E5%A1%AB%E5%B8%A7%E5%8F%B7%22%5D%0A%20%20PTE%20--%3E%20TLB%5B%22TLB%20%E6%9B%B4%E6%96%B0%EF%BC%8C%E9%87%8D%E8%AF%95%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">初学者容易以为「加大 swap 机器就快」。实际换入是 major 缺页，每次一次块 I/O，毫秒级，比内存访问慢四五个数量级；swap 是崩溃前的缓冲垫，不是性能手段——顶满时 CPU 全在等盘。</span></p><p><a href="/cs/tlb-translate">TLB</a> 在换出后必须不含该 VPN，shootdown 规则照旧。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 zswap 内存压缩池的调参。不保证 swap 文件在所有文件系统上性能相同。无 swap 的机器把压力直接交给 OOM，下一课。也不把 NUMA 的每节点 swap 写进主干。</p><p>后课默认：匿名页有槽可去。槽与帧都尽时如何选进程牺牲，下一课 OOM killer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>swap 按页槽备份匿名页，不走用户路径名。</li><li>换入仍是缺页路径上的 major I/O。</li><li>槽与内存双尽是 OOM 的缺口。</li><li>出处：Tanenbaum <em>MOS</em>；Bovet and Cesati, <em>ULK</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const u=l(A,[["render",m]]);export{f as __pageData,u as default};
